import React, { useState, useEffect, useMemo } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Icon from 'components/AppIcon';
import api from '../../lib/api';
import { ProgressContext } from '../../contexts/ProgressContext';
import LoadingState from '../../components/ui/LoadingState';

const SUBJECT_COLORS = {
  mathematics: 'primary',
  programming: 'accent',
  science: 'success',
  history: 'secondary',
  geography: 'warning',
};

const CourseCatalog = () => {
  const { learningNodes = [], loading: progressLoading } = React.useContext(ProgressContext) || {};
  const [catalog, setCatalog] = useState([]);
  const [loading, setLoading] = useState(true);
  const [subject, setSubject] = useState('all');
  const [difficulty, setDifficulty] = useState('all');
  const [search, setSearch] = useState('');
  const navigate = useNavigate();

  const [error, setError] = useState(null);

  useEffect(() => {
    api.getCatalog()
      .then((data) => setCatalog(Array.isArray(data) ? data : []))
      .catch((err) => setError(err.message || 'Failed to load catalog'))
      .finally(() => setLoading(false));
  }, []);

  const progressMap = useMemo(() => {
    const map = {};
    learningNodes.forEach((n) => { map[n.id] = n; });
    return map;
  }, [learningNodes]);

  const filtered = useMemo(() => {
    return catalog.filter((item) => {
      if (subject !== 'all' && item.subject !== subject) return false;
      if (difficulty !== 'all' && item.difficulty !== difficulty) return false;
      if (search && !(item.title || '').toLowerCase().includes(search.toLowerCase())) return false;
      return true;
    });
  }, [catalog, subject, difficulty, search]);

  const subjects = useMemo(() => [...new Set(catalog.map((c) => c.subject))], [catalog]);

  if (loading || progressLoading) return <LoadingState message="Loading catalog..." />;
  if (error) return (
    <div className="min-h-screen bg-background flex items-center justify-center">
      <div className="text-center">
        <p className="text-text-secondary mb-4">{error}</p>
        <button onClick={() => { setLoading(true); setError(null); api.getCatalog().then((d) => setCatalog(Array.isArray(d) ? d : [])).catch((e) => setError(e.message)).finally(() => setLoading(false)); }} className="btn btn-primary">Retry</button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto px-4 py-8">
        <div className="mb-8">
          <h1 className="text-2xl lg:text-3xl font-heading font-bold text-text-primary mb-2">
            Course Catalog
          </h1>
          <p className="text-text-secondary">
            {catalog.length} adaptive modules across {subjects.length} subjects
          </p>
        </div>

        <div className="flex flex-col lg:flex-row gap-4 mb-8 p-4 bg-surface border border-border rounded-lg">
          <input
            type="search"
            placeholder="Search courses..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="input flex-1"
          />
          <select value={subject} onChange={(e) => setSubject(e.target.value)} className="input lg:w-48">
            <option value="all">All Subjects</option>
            {subjects.map((s) => (
              <option key={s} value={s}>{s.charAt(0).toUpperCase() + s.slice(1)}</option>
            ))}
          </select>
          <select value={difficulty} onChange={(e) => setDifficulty(e.target.value)} className="input lg:w-40">
            <option value="all">All Levels</option>
            <option value="beginner">Beginner</option>
            <option value="intermediate">Intermediate</option>
            <option value="advanced">Advanced</option>
          </select>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
          {filtered.map((course) => {
            const progress = progressMap[course.id]?.progress || 0;
            const color = SUBJECT_COLORS[course.subject] || 'primary';
            return (
              <article key={course.id} className="card p-6 flex flex-col hover:shadow-warm-md transition-shadow">
                <div className="flex items-start justify-between mb-3">
                  <span className={`text-xs px-2 py-1 rounded-full bg-${color}-50 text-${color} capitalize`}>
                    {course.subject}
                  </span>
                  <span className="text-xs text-text-secondary capitalize">{course.difficulty}</span>
                </div>
                <h2 className="text-lg font-heading font-semibold text-text-primary mb-2">{course.title}</h2>
                <p className="text-sm text-text-secondary flex-1 mb-4">{course.description}</p>
                <div className="mb-4">
                  <div className="flex justify-between text-xs text-text-secondary mb-1">
                    <span>Progress</span>
                    <span>{Math.round(progress)}%</span>
                  </div>
                  <div className="w-full bg-surface-100 rounded-full h-2">
                    <div
                      className={`bg-${color} h-2 rounded-full transition-all`}
                      style={{ width: `${Math.min(progress, 100)}%` }}
                    />
                  </div>
                </div>
                <div className="flex items-center justify-between text-xs text-text-secondary mb-4">
                  <span><Icon name="Clock" size={14} className="inline mr-1" />{course.estimatedTime}</span>
                  {course.prerequisite && (
                    <span title="Has prerequisite">Prereq required</span>
                  )}
                </div>
                <button
                  onClick={() => navigate(`/interactive-learning-session/${course.id}`)}
                  className="btn btn-primary w-full py-2 text-sm"
                >
                  {progress > 0 ? 'Continue' : 'Start Module'}
                </button>
              </article>
            );
          })}
        </div>

        {filtered.length === 0 && (
          <p className="text-center text-text-secondary py-12">No courses match your filters.</p>
        )}
      </div>
    </div>
  );
};

export default CourseCatalog;
